	@Test
	void languageTaggedLiteralsAreRejectedAsTemporalValuesButAcceptedAsText() {
		assertEvaluationError("tagged date", () -> new DayOfWeek().evaluate(VF, VF.createLiteral("2024-05-17", "en")));
		assertEvaluationError("tagged dateTime",
				() -> new DateAdd().evaluate(VF, VF.createLiteral("2024-05-17T10:11:12Z", "en"), dur("P1D")));
		// pins current behaviour: a duration must be typed or an xsd:string, a language-tagged duration is rejected
		assertEvaluationError("tagged duration", () -> new DateAdd().evaluate(VF, DT, VF.createLiteral("P1D", "en")));
		// pins current behaviour: unit names, patterns, zone ids and the parseDate input accept language-tagged text
		assertThat(new DateTrunc().evaluate(VF, VF.createLiteral("day", "en"), DT))
				.isEqualTo(dt("2024-05-17T00:00:00Z"));
		assertThat(new ParseDate().evaluate(VF, VF.createLiteral("17/05/2024", "en"), str("dd/MM/yyyy")))
				.isEqualTo(date("2024-05-17"));
		assertThat(new DateFormat().evaluate(VF, DT, VF.createLiteral("yyyy", "en"))).isEqualTo(str("2024"));
		assertThat(new AtTimeZone().evaluate(VF, DT, VF.createLiteral("UTC", "en"))).isEqualTo(DT);
	}

	@Test
	void resultsHaveCanonicalLexicalForms() {
		assertThat(new DateTrunc().evaluate(VF, str("second"), dt("2024-05-17T10:11:12.500+01:00")).getLabel())
				.isEqualTo("2024-05-17T10:11:12+01:00");
		assertThat(new DateAdd().evaluate(VF, dt("2024-05-17T10:11:12.500+00:00"), dur("PT0S")).getLabel())
				.isEqualTo("2024-05-17T10:11:12.5Z");
		Literal seconds = new Epoch().evaluate(VF, dt("2001-09-09T01:46:40Z"));
		assertThat(seconds.getLabel()).isEqualTo("1000000000");
		assertThat(seconds.getDatatype()).isEqualTo(CoreDatatype.XSD.DECIMAL.getIri());
		Literal millis = new EpochMillis().evaluate(VF, dt("2001-09-09T01:46:40Z"));
		assertThat(millis.getLabel()).isEqualTo("1000000000000");
		assertThat(millis.getDatatype()).isEqualTo(CoreDatatype.XSD.INTEGER.getIri());
		Literal monday = new DayOfWeek().evaluate(VF, date("2024-05-13"));
		assertThat(monday.getLabel()).isEqualTo("1");
		assertThat(monday.getDatatype()).isEqualTo(CoreDatatype.XSD.INTEGER.getIri());
		assertThat(new Age().evaluate(VF, dt("2024-01-01T00:00:00.500Z"), dt("2024-01-01T00:00:00Z")).getLabel())
				.isEqualTo("PT0.5S");
		assertThat(new FromUnixtime().evaluate(VF, decimal("1.50")).getLabel()).isEqualTo("1970-01-01T00:00:01.5Z");
		assertThat(new DateFormat().evaluate(VF, DT, str("yyyy")).getDatatype())
				.isEqualTo(CoreDatatype.XSD.STRING.getIri());
	}

